INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('was-ist-die-plattform', 'allgemein', NULL, NULL, 'Was ist die BDAS-Plattform?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Die Plattform ist das zentrale System des BDAS für Mitglieder-, Event- und Gruppendaten. Sie ersetzt die frühere Mischung aus WordPress, WhatsApp und Tabellen."}]},{"type":"paragraph","content":[{"type":"text","text":"Sie besteht aus zwei Bereichen: dem öffentlichen Auftritt (Startseite, Veranstaltungen, Gruppen, Spenden) und dem angemeldeten Dashboard mit den internen Funktionen."}]}]}'::jsonb, 'published', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('oeffentlich-vs-dashboard', 'allgemein', NULL, NULL, 'Was ist der Unterschied zwischen öffentlicher Seite und Dashboard?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Der öffentliche Bereich ist für alle sichtbar und zeigt Marketing-Inhalte, die Veranstaltungsliste, die Gruppenübersicht und die Spendenseite. Das Dashboard ist der angemeldete Arbeitsbereich; was du dort siehst, hängt von deiner Rolle ab."}]},{"type":"paragraph","content":[{"type":"text","text":"Zum Dashboard","marks":[{"type":"link","attrs":{"href":"/dashboard"}}]}]}]}'::jsonb, 'published', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('registrierung-login', 'allgemein', NULL, 'profil', 'Wie registriere und melde ich mich an?', '{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mit E-Mail-Adresse und Passwort registrieren."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Die Bestätigungs-E-Mail öffnen und den Verifizierungslink anklicken — die Verifizierung ist Pflicht, bevor Rollen vergeben werden können."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Danach jederzeit über „Anmelden“ einloggen. Passwort vergessen? Über den Zurücksetzen-Link neu setzen."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Zur Anmeldung","marks":[{"type":"link","attrs":{"href":"/anmelden"}}]}]}]}'::jsonb, 'published', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('rollenmodell', 'allgemein', NULL, 'administration', 'Welche Rollen gibt es und wie funktionieren sie?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Jede Person hat eine Basisrolle (z. B. Mitglied) und dazu beliebig viele zugewiesene Rollen, die auf eine Gruppe begrenzt sein können."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mitglied — registriertes, aktives Mitglied einer Hochschulgruppe."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Vorstand (Lokaler Vorstand) — verwaltet die eigene Gruppe."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"LEAD — höchste Vertrauensrolle einer Gruppe; darf Rollen in der Gruppe vergeben."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Event Organisator — darf Veranstaltungen der Gruppe verwalten."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Seiten Editor — darf die öffentliche Gruppenseite bearbeiten."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bundesvorstand — föderationsweite Verwaltung über alle Gruppen."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Alumni — ausgeschiedenes Mitglied; meldet sich nicht mehr für Veranstaltungen an, kann aber weiterhin Blog-Beiträge verfassen."}]}]}]}]}'::jsonb, 'published', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('scope-switcher', 'allgemein', NULL, 'administration', 'Ich habe mehrere Rollen — wie wechsle ich zwischen ihnen?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Wer mehrere Zuständigkeiten hat (z. B. LEAD einer Gruppe und Bundesvorstand), wechselt oben in der Seitenleiste des Dashboards über den Bereichs-Umschalter zwischen den Ansichten — die URL musst du dafür nicht wechseln."}]}]}'::jsonb, 'published', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('zugriff-sicherheit', 'allgemein', NULL, 'administration', 'Wer darf was sehen?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Jede Dashboard-Seite ist an deine Rolle gebunden. Ohne passende Zuweisung wirst du automatisch zurück auf deinen erlaubten Bereich geleitet. So sieht niemand Daten, für die er nicht zuständig ist."}]}]}'::jsonb, 'published', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('account-praeferenzen', 'allgemein', NULL, 'profil', 'Wo ändere ich meine Kontoeinstellungen?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unter „Mein Konto“ verwaltest du deine Zugangsdaten und deine E-Mail-Präferenzen — also welche Benachrichtigungskategorien du erhalten möchtest. Transaktionale E-Mails (z. B. Verifizierung, Anmeldebestätigungen) sind verpflichtend und nicht abwählbar."}]},{"type":"paragraph","content":[{"type":"text","text":"Zu meinem Konto","marks":[{"type":"link","attrs":{"href":"/account"}}]}]}]}'::jsonb, 'published', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('overview', 'bundesvorstand', NULL, 'administration', 'Was zeigt mir die Übersicht?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Die Übersicht zeigt die föderationsweiten Kennzahlen: aktive Mitglieder, Neuanmeldungen der letzten 30 Tage, Anzahl aktiver Gruppen und anstehende Veranstaltungen — dazu einen Verlaufs-Chart der Anmeldungen."}]},{"type":"paragraph","content":[{"type":"text","text":"Zur Übersicht","marks":[{"type":"link","attrs":{"href":"/federal/overview"}}]}]}]}'::jsonb, 'published', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('mitglieder-events-gruppen', 'bundesvorstand', NULL, 'administration', 'Wie sehe ich alle Mitglieder, Events und Gruppen?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Die Mitgliedertabelle listet alle Mitglieder der Föderation, filterbar nach Gruppe und Status. Analog gibt es eine Tabelle aller Veranstaltungen und die Gruppen-Registry mit allen Status, inklusive ruhender und archivierter Gruppen."}]},{"type":"paragraph","content":[{"type":"text","text":"Alle Mitglieder","marks":[{"type":"link","attrs":{"href":"/federal/members"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Gruppen verwalten","marks":[{"type":"link","attrs":{"href":"/federal/groups"}}]}]}]}'::jsonb, 'published', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('gruppen-verwalten', 'bundesvorstand', NULL, 'gruppen', 'Wie lege ich eine Gruppe an oder archiviere sie?', '{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"„Gruppen“ im Bundesverband-Bereich öffnen."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Neue Gruppe anlegen oder eine bestehende bearbeiten bzw. archivieren."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Archivierte Gruppen verwaltet nur noch der Bundesvorstand — ein lokaler Vorstand kann sie nicht mehr bearbeiten."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Zur Gruppen-Registry","marks":[{"type":"link","attrs":{"href":"/federal/groups"}}]}]}]}'::jsonb, 'published', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('rollenvergabe', 'bundesvorstand', NULL, 'administration', 'Wie vergebe ich Vorstandsrollen?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unter „Rollen“ im Bundesverband-Bereich vergibst und entziehst du direkt zwei Rollen: Bundesvorstand und LEAD einer Gruppe. Die übrigen lokalen Rollen — Vorstand, Event Organisator, Seiten Editor — vergibt die LEAD-Person auf der Vorstandsseite der jeweiligen Gruppe; als Bundesvorstand kannst du das dort ebenfalls erledigen."}]},{"type":"paragraph","content":[{"type":"text","text":"Jede Vergabe und jeder Entzug erscheint im Audit-Log."}]},{"type":"paragraph","content":[{"type":"text","text":"Zur Rollenvergabe","marks":[{"type":"link","attrs":{"href":"/federal/roles"}}]}]}]}'::jsonb, 'published', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('pool', 'bundesvorstand', NULL, 'administration', 'Was ist der „Ohne Gruppe“-Bereich?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hier siehst du Mitglieder ohne Gruppenzuordnung sowie jede föderationsweit offene Bewerbung — auch für Gruppen ohne aktiven Vorstand, wo sonst niemand entscheiden könnte."}]},{"type":"paragraph","content":[{"type":"text","text":"Zum Pool","marks":[{"type":"link","attrs":{"href":"/federal/pool"}}]}]}]}'::jsonb, 'published', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('dateien', 'bundesvorstand', NULL, 'dateien', 'Wo sehe ich alle Dateien?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Im Datei-Bereich hast du als einzige Rolle Zugriff auf die Ordner jeder Gruppe sowie auf den föderationsweiten Bundesvorstands-Ordner."}]},{"type":"paragraph","content":[{"type":"text","text":"Zu allen Dateien","marks":[{"type":"link","attrs":{"href":"/federal/files"}}]}]}]}'::jsonb, 'published', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('blog-moderation', 'bundesvorstand', NULL, NULL, 'Wie moderiere ich gemeldete Blog-Beiträge?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Gemeldete Beiträge landen in der Meldungs-Queue — nur für den Bundesvorstand sichtbar. Du kannst dort einen Beitrag bearbeiten oder löschen, oder die Meldung verwerfen. Beiträge mit Sichtbarkeit „Nur Vorstände“ sind ebenfalls nur für den Bundesvorstand lesbar."}]},{"type":"paragraph","content":[{"type":"text","text":"Zur Meldungs-Queue","marks":[{"type":"link","attrs":{"href":"/blog/meldungen"}}]}]}]}'::jsonb, 'published', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('lb-uebersicht-roster', 'vorstand', 'local_board', 'administration', 'Was kann ich als Vorstand verwalten?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Du siehst die Übersicht deiner Gruppe (Kennzahlen und Verlaufs-Chart) und verwaltest den Mitgliederbestand: Beitrittsanfragen und eingehende Gruppenwechsel per Klick annehmen oder ablehnen."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Im Dashboard in den Bereich deiner Gruppe wechseln."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"„Mitglieder“ öffnen für den Bestand, „Bewerbungen“ für offene Anfragen."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Zum Gruppen-Dashboard","marks":[{"type":"link","attrs":{"href":"/dashboard"}}]}]}]}'::jsonb, 'published', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('lb-events', 'vorstand', 'local_board', 'events', 'Wie lege ich eine Veranstaltung an?', '{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Im Gruppenbereich „Events“ öffnen."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Neue Veranstaltung erstellen: Titel, Datum, Ort und Plätze festlegen."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Speichern — Mitglieder können sich anschließend an- und abmelden; volle Events führen eine Warteliste."}]}]}]}]}'::jsonb, 'published', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('lb-profil-vs-seite', 'vorstand', 'local_board', 'gruppen', 'Wo bearbeite ich das Gruppenprofil — und wo die Gruppenseite?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Das sind zwei verschiedene Dinge. Das Gruppenprofil — Name, Stadt, Standort auf der Karte — bearbeitest du als jeder Vorstand unter „Profil“. Die öffentliche Gruppenseite (Inhalte, Text, Bilder) darf nur die LEAD-Person oder ein Seiten Editor bearbeiten."}]}]}'::jsonb, 'published', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('lb-dateien', 'vorstand', 'local_board', 'dateien', 'Wo finde ich meine Gruppendateien?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Im Datei-Bereich deiner Gruppe hast du Zugriff auf den Mitglieder-Ordner und den Vorstands-Ordner deiner Gruppe."}]}]}'::jsonb, 'published', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('lb-grenzen', 'vorstand', 'local_board', 'administration', 'Was kann ich als Vorstand NICHT?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ein einfacher Vorstand kann weder die öffentliche Gruppenseite bearbeiten noch Rollen vergeben. Beides ist der LEAD-Rolle vorbehalten — die es wiederum an Seiten Editor bzw. Event Organisator delegieren kann."}]}]}'::jsonb, 'published', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('lead-was-zusaetzlich', 'vorstand', 'local_board_lead', 'administration', 'Was kann ich als LEAD zusätzlich zum Vorstand?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"LEAD ist die höchste Vertrauensrolle deiner Gruppe. Zusätzlich zu allen Vorstandsrechten darfst du auf der Vorstandsseite deiner Gruppe Rollen vergeben und die öffentliche Gruppenseite bearbeiten."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"„Vorstand“, „Event Organisator“ oder „Seiten-Editor“ an Mitglieder deiner Gruppe vergeben oder entziehen."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Die öffentliche Gruppenseite selbst bearbeiten."}]}]}]}]}'::jsonb, 'published', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('lead-grenzen', 'vorstand', 'local_board_lead', 'administration', 'Wo hört die LEAD-Rolle auf?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Archivierte Gruppen kann auch ein LEAD nicht mehr verwalten — das übernimmt der Bundesvorstand. Eine weitere LEAD-Person oder die Bundesvorstands-Rolle vergibt ebenfalls nur der Bundesvorstand."}]}]}'::jsonb, 'published', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('eo-scope', 'vorstand', 'event_organizer', 'events', 'Was darf ich als Event Organisator?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Du bist Delegierter für die Veranstaltungen deiner Gruppe: Events anlegen, bearbeiten und absagen — ohne den vollen Vorstandszugriff. Mitgliederverwaltung und Rollenvergabe gehören nicht dazu."}]}]}'::jsonb, 'published', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('pe-scope', 'vorstand', 'page_editor', 'gruppen', 'Was darf ich als Seiten Editor?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Du darfst ausschließlich die öffentliche Seite deiner Gruppe bearbeiten — Inhalte, Text und Darstellung. Das Gruppenprofil (Name/Stadt/Standort) und weitere Vorstandsfunktionen sind mit dieser Rolle nicht verbunden."}]}]}'::jsonb, 'published', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('profil', 'mitglieder', NULL, 'profil', 'Wie pflege ich mein Profil?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unter „Mein Konto“ verwaltest du deine persönlichen Angaben und Kontoeinstellungen."}]},{"type":"paragraph","content":[{"type":"text","text":"Zu meinem Konto","marks":[{"type":"link","attrs":{"href":"/account"}}]}]}]}'::jsonb, 'published', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('events', 'mitglieder', NULL, 'events', 'Wie melde ich mich für Veranstaltungen an?', '{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Die Veranstaltungsliste öffnen und ein Event auswählen."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An- oder abmelden. Ist das Event voll, kommst du auf die Warteliste."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Wird ein Platz frei, rückst du automatisch nach und wirst per E-Mail benachrichtigt."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Zu den Veranstaltungen","marks":[{"type":"link","attrs":{"href":"/events"}}]}]}]}'::jsonb, 'published', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('interne-infos', 'mitglieder', NULL, NULL, 'Wo bekomme ich interne Infos, die nicht öffentlich sind?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Über den Blog: Beiträge mit Sichtbarkeit „Nur Mitglieder“ sind ausschließlich für angemeldete, aktive Mitglieder lesbar. Ein separates Mitgliederverzeichnis gibt es nicht — die eigene Gruppe erreichst du über deren öffentliche Gruppenseite."}]},{"type":"paragraph","content":[{"type":"text","text":"Zum Blog","marks":[{"type":"link","attrs":{"href":"/blog"}}]}]}]}'::jsonb, 'published', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('gruppenwechsel', 'mitglieder', NULL, 'gruppen', 'Wie wechsle ich die Gruppe?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Du kannst einen Gruppenwechsel beantragen. Über die Aufnahme entscheidet der Vorstand der Zielgruppe."}]}]}'::jsonb, 'published', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('mitglieder-dateien', 'mitglieder', NULL, 'dateien', 'Wo finde ich geteilte Dateien?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Als Mitglied hast du Zugriff auf den Mitglieder-Ordner im Dateibereich mit Dokumenten und Vorlagen sowie auf den Ordner deiner eigenen Gruppe."}]}]}'::jsonb, 'published', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('blog-schreiben', 'mitglieder', NULL, NULL, 'Kann ich selbst Blog-Beiträge schreiben?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ja, wenn du als aktives Mitglied geführt wirst. Du kannst eigene Beiträge jederzeit bearbeiten oder löschen und fremde Beiträge melden, wenn sie gegen die Regeln verstoßen."}]}]}'::jsonb, 'published', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO faq_entries (id, section, subgroup, topic_id, question, body, status, position) VALUES ('alumni', 'mitglieder', NULL, 'profil', 'Was ändert sich als Alumni?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Als Alumni giltst du nicht mehr als aktives Mitglied. Du kannst weiterhin Blog-Beiträge verfassen. Für Veranstaltungen kannst du dich erst wieder anmelden, sobald du erneut als aktiv geführt wirst."}]}]}'::jsonb, 'published', 6) ON CONFLICT (id) DO NOTHING;
